"use client";

import { create } from "zustand";
import { persist } from "zustand/middleware";

export type MartUser = {
  id: string;
  email: string;
  name: string;
  role: string;
  storeId?: string | null;
};

type AuthState = {
  token: string | null;
  refreshToken: string | null;
  user: MartUser | null;
  _hasHydrated: boolean;
  setCredentials: (data: {
    accessToken: string;
    refreshToken: string;
    user: MartUser;
  }) => void;
  setHasHydrated: (value: boolean) => void;
  logout: () => void;
  getToken: () => string | null;
};

export const useAuthStore = create<AuthState>()(
  persist(
    (set, get) => ({
      token: null,
      refreshToken: null,
      user: null,
      _hasHydrated: false,
      setCredentials: (data) =>
        set({
          token: data.accessToken,
          refreshToken: data.refreshToken,
          user: data.user,
        }),
      setHasHydrated: (value) => set({ _hasHydrated: value }),
      logout: () =>
        set({ token: null, refreshToken: null, user: null }),
      getToken: () => get().token,
    }),
    {
      name: "zimcart-mart-auth",
      partialize: (s) => ({
        token: s.token,
        refreshToken: s.refreshToken,
        user: s.user,
      }),
      onRehydrateStorage: () => (state) => {
        useAuthStore.getState().setHasHydrated(true);
      },
    }
  )
);

export function isMartRole(role: string): boolean {
  return ["ADMIN", "MERCHANT", "STORE_MANAGER"].includes(role);
}
